/// The gallery's example of `ColorWheel`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_diameter = args.number("diameter") as f32;
        let arg_label = args.text("label");
        let arg_disabled = args.bool("disabled");

        let tint = State::new(HueSaturation::new(30.0, 0.4));
        let shown = tint.clone();
        HStack::new((
            {
                let mut it = ColorWheel::new(tint.binding());
                it = it.diameter(arg_diameter);
                it = it.label(arg_label.clone());
                it = it.disabled(arg_disabled);
                it
            },
            Text::bound(&shown, |v| format!("{:.0}°, {:.0}%", v.hue, v.saturation * 100.0))
                .style(TextStyle::Callout)
                .foreground(Semantic::InkMuted),
        ))
        .spacing(16.0)
    })
}

impl ComponentBook for ColorWheel {
    fn book() -> Meta {
        Meta::new("Media/ColorWheel", render)
            .summary("Hue and saturation on a disc, by a drag or the arrow keys.")
            .arg(ArgType::number("diameter", 160.0, 0.0, 640.0, 1.0))
            .arg(ArgType::text("label", "Shadows"))
            .arg(ArgType::bool("disabled", false))
            .story("Example", Args::new())
            .story("Disabled", Args::new().with("disabled", true))
    }
}
